// Clean the Google Maps results: remove duplicates, keep only the fields we need
const form = $('Form').first().json;
const limit = Math.min(Number(form.count) || 10, 20);
const seen = new Set();
const out = [];

for (const item of $input.all()) {
  const p = item.json;
  if (!p.title) continue;
  const key = (p.title + '|' + (p.address || '')).toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({ json: {
    date: new Date().toISOString().slice(0, 10),
    niche: form.niche,
    city: form.city,
    service: form.service,
    language: form.language,
    business_name: p.title,
    category: p.categoryName || '',
    rating: p.totalScore ?? '',
    reviews: p.reviewsCount ?? 0,
    phone: p.phone || '',
    website: p.website || '',
    maps_url: p.url || ''
  }});
}

if (out.length === 0) {
  throw new Error('No businesses found. Check the niche/city or your Apify token.');
}
return out.slice(0, limit);

// Read the website HTML and detect simple signals
const lead = $('Loop Over Items').item.json;
const html = String($input.first().json.html || '');
const lower = html.toLowerCase();
const loaded = html.length > 500;

// Many sites block automated checks. If we could not read it, we do NOT know anything about it.
if (!loaded) {
  return [{ json: {
    ...lead,
    site_loaded: 'unknown',
    has_booking: 'unknown',
    has_chat: 'unknown',
    has_whatsapp: 'unknown',
    has_contact_form: 'unknown',
    mobile_friendly: 'unknown',
    copyright_year: 'unknown',
    site_text: 'The website exists but could not be checked automatically. Do not make any claim about the website itself.'
  }}];
}

const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 2500);

const years = [...lower.matchAll(/(?:©|&copy;|copyright)\s*(\d{4})/g)].map(m => Number(m[1]));

return [{ json: {
  ...lead,
  site_loaded: true,
  has_booking: /calendly|acuityscheduling|book now|book online|book an appointment|schedule an appointment|booking/.test(lower),
  has_chat: /intercom|tawk\.to|drift\.com|livechat|crisp\.chat|tidio|zendesk|hs-scripts/.test(lower),
  has_whatsapp: /wa\.me|api\.whatsapp\.com/.test(lower),
  has_contact_form: /<form/.test(lower),
  mobile_friendly: /name=["']viewport["']/.test(lower),
  copyright_year: years.length ? Math.max(...years) : 'unknown',
  site_text: text
}}];

// Build the prompt for the AI
const lead = $input.first().json;

const prompt = `You are a sharp B2B sales researcher for a freelancer who sells ${lead.service} to local businesses.

Business:
- Name: ${lead.business_name}
- Category: ${lead.category}
- City: ${lead.city}
- Google rating: ${lead.rating} from ${lead.reviews} reviews
- Website: ${lead.website || 'none'}

Website checks ("unknown" means we could not check it):
- Website loaded: ${lead.site_loaded}
- Online booking: ${lead.has_booking}
- Live chat: ${lead.has_chat}
- WhatsApp button: ${lead.has_whatsapp}
- Contact form: ${lead.has_contact_form}
- Mobile friendly: ${lead.mobile_friendly}
- Latest copyright year: ${lead.copyright_year}

Website text (may be empty):
${lead.site_text}

Strict rules:
- Never claim a website is broken, slow, not loading or not mobile friendly unless the checks above say false.
- If a check is "unknown", do not mention it at all.
- Our checks can miss chat widgets and forms loaded by JavaScript, so say "I could not find" instead of "you don't have".
- Use only the data above. Do not invent facts, numbers or results.

Tasks:
1. gaps: the 1 or 2 most likely problems that cost this business customers or time. Keep each under 20 words.
2. opportunity_score: 1 to 10, how likely this business needs ${lead.service}.
3. best_offer: one sentence describing the specific automation you would offer them.
4. email_subject: under 8 words, specific to this business, no clickbait.
5. email_body: under 90 words. Mention one real detail about their business. Explain the problem and the result in plain words. End with a simple low pressure question. No hype, no guaranteed results.
6. dm_message: under 40 words, same idea, for WhatsApp or Instagram.

Write email_subject, email_body and dm_message in ${lead.language}.`;

return [{ json: { lead, prompt } }];

// Business has no website: that is an opportunity by itself
const lead = $input.first().json;
return [{ json: {
  ...lead,
  site_loaded: false,
  has_booking: false,
  has_chat: false,
  has_whatsapp: false,
  has_contact_form: false,
  mobile_friendly: false,
  copyright_year: null,
  site_text: 'Business has no website.'
}}];
